import numpy as np
from rdkit import Chem

m = Chem.MolFromXYZFile("optimized.xyz")
print("atoms:", m.GetNumAtoms())
conf = m.GetConformer()
pos = conf.GetPositions()
syms = [a.GetSymbol() for a in m.GetAtoms()]

def dist(i,j): return np.linalg.norm(pos[i]-pos[j])

au = syms.index("Au")
ps  = [i for i,s in enumerate(syms) if s=="P"]
ss  = [i for i,s in enumerate(syms) if s=="S"]
print("Au idx", au, "P idx", ps, "S idx", ss)
for p in ps: print(f"Au-P({p}) = {dist(au,p):.3f}")
for s in ss: print(f"Au-S({s}) = {dist(au,s):.3f}")

# S-H check
for s in ss:
    for i,h in enumerate(syms):
        if h=="H" and dist(s,i)<1.6:
            print(f"S({s})-H({i}) = {dist(s,i):.3f}")

# angles around Au
def ang(i,j,k):
    v1=pos[i]-pos[j]; v2=pos[k]-pos[j]
    return np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
nbr = ps+ss
for a in range(len(nbr)):
    for b in range(a+1,len(nbr)):
        print(f"angle {nbr[a]}-Au-{nbr[b]} = {ang(nbr[a],au,nbr[b]):.1f}")

# count elements
from collections import Counter
print(Counter(syms))
EOF
python3 check.py
